import React from 'react';
import { useSelector } from 'react-redux';
import { PlusOutlined } from '@ant-design/icons';
import { Button, Spin } from 'antd';
import RecipeListTree from './RecipeListTree';
import './RecipeList.css';

const RecipeList = ({ 
  recipes, 
  onSelectRecipe, 
  activeurlPermalink,
  isGoogleDriveConnected,
  userInfo,
  onSignIn,
  onSignOut,
  onSettingsChange, // New prop for settings changes
  onCreateNewRecipe,
  editingEnabled,
  onEditingToggle,
  showDemoRecipes,
  onDemoRecipesToggle,
  isLoading,
  message
}: any) => {
  const { driveRecipes } = useSelector((state: any) => state.recipes);

  // Local function to count total recipes
  const getTotalRecipesCount = () => {
    const localCount = Object.values(recipes as any).reduce((total: number, sectionRecipes: any) => 
      total + (Array.isArray(sectionRecipes) ? sectionRecipes.length : 0), 0
    );
    const driveCount = driveRecipes.length;
    return localCount + driveCount;
  };

  return (
    <div className="recipe-list">
      {/* Recipe Library Header */}
      <div className="recipe-library-header">
        <div className="library-header-content">
          <Button 
            type="primary"
            icon={<PlusOutlined />}
            onClick={() => {
              console.log('🎯 New Recipe button clicked');
              onCreateNewRecipe();
            }}
            loading={isLoading}
            style={{
              background: 'linear-gradient(90deg, #6a11cb 0%, #2575fc 100%)',
              borderColor: 'transparent'
            }}
          >
            New Recipe
          </Button>
          
          <div className="library-info">
            <h3 style={{ margin: 0, marginBottom: '0.25rem' }}>
              Recipes Library
            </h3>
            <p style={{ margin: 0, color: '#666', fontSize: '0.9rem' }}>
              {getTotalRecipesCount()} {getTotalRecipesCount() === 1 ? 'recipe' : 'recipes'} in library
            </p>
            {isLoading && (
              <div style={{ 
                display: 'flex', 
                alignItems: 'center', 
                justifyContent: 'center',
                gap: '0.25rem',
                marginTop: '0.25rem'
              }}>
                <Spin size="small" />
                <span>Loading...</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Recipe Tree */}
      <RecipeListTree
        recipes={recipes}
        driveRecipes={driveRecipes}
        onSelectRecipe={onSelectRecipe}
        activeRecipePermalink={activeurlPermalink}
      />
    </div>
  );
};

export default RecipeList;
